type Toast = { title: string; detail: string } | null;

function downloadSimplePdf(filename: string, title: string, rows: string[]) {
  const clean = (value: string) => value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[\\()]/g, "\\$&").slice(0, 110);
  const lines = [title, `Gerado em ${new Date().toLocaleString("pt-BR")}`, "", ...rows].map(clean);
  const stream = ["BT", "/F1 12 Tf", "50 780 Td", ...lines.flatMap((line, index) => [`(${line}) Tj`, index < lines.length - 1 ? "0 -18 Td" : ""]), "ET"].join("\n");
  const objects = [`<< /Type /Catalog /Pages 2 0 R >>`, `<< /Type /Pages /Kids [3 0 R] /Count 1 >>`, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>`, `<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>`, `<< /Length ${new TextEncoder().encode(stream).length} >>\nstream\n${stream}\nendstream`];
  let pdf = "%PDF-1.4\n"; const offsets = [0]; objects.forEach((object, index) => { offsets[index + 1] = new TextEncoder().encode(pdf).length; pdf += `${index + 1} 0 obj\n${object}\nendobj\n`; }); const xref = new TextEncoder().encode(pdf).length; pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.slice(1).map((offset) => `${String(offset).padStart(10, "0")} 00000 n `).join("\n")}\ntrailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  const url = URL.createObjectURL(new Blob([pdf], { type: "application/pdf" })); const link = document.createElement("a"); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url);
}

function ReportActions({ title, filename, rows, onToast }: { title: string; filename: string; rows: string[]; onToast: (toast: NonNullable<Toast>) => void }) {
  const exportPdf = () => { downloadSimplePdf(filename, title, rows); onToast({ title: "PDF exportado", detail: `${title} foi baixado para o dispositivo.` }); };
  const print = () => { const previous = document.title; document.title = title; window.print(); window.setTimeout(() => { document.title = previous; }, 1000); };
  return <div className="mb-5 flex flex-wrap justify-end gap-2"><Button onClick={exportPdf} variant="outline" className="h-9 rounded-xl border-[#e4e0d7] text-xs font-semibold text-[#78643a]"><FileDown size={14} /> Exportar PDF</Button><Button onClick={print} variant="outline" className="h-9 rounded-xl border-[#e4e0d7] text-xs font-semibold text-[#78643a]"><Printer size={14} /> Imprimir</Button></div>;
}

